import { Component, inject, computed, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { WatchItem } from '../movie';
import { WatchlistStore } from '../watchlist-store';

@Component({
  imports: [RouterLink],
  selector: 'app-watchlist',
  styleUrl: './watchlist.scss',
  templateUrl: './watchlist.html',
})
export class Watchlist {
  store = inject(WatchlistStore)
  movies = this.store.items

  readonly imageBase = 'https://image.tmdb.org/t/p/w92';

  watchedCount = this.store.watchedCount
  progress = computed(() => this.movies().length ? (this.watchedCount() / this.movies().length) * 100 : 0)
  announcement = signal('')

  toggleWatched(id: number) {
    this.store.toggleWatched(id)
  }

  // Mouse convenience: clicking blank space on a row toggles it, but clicks on the
  // checkbox, title link or remove button keep their own behaviour.
  onRowClick(event: MouseEvent, id: number) {
    if ((event.target as HTMLElement).closest('a, button, input')) {
      return;
    }
    this.toggleWatched(id)
  }

  remove(movie: WatchItem) {
    this.store.remove(movie.id)
    this.announcement.set(`Removed ${movie.title} from your watchlist`)
  }

  // Bulk action: drop every watched movie in one go. The count is captured before
  // the store is emptied so the announcement can say how many entries were removed.
  clearWatched(): void {
    const removed = this.watchedCount()
    this.store.clearWatched()
    this.announcement.set(
      removed === 1
        ? 'Removed 1 watched movie from your watchlist'
        : `Removed ${removed} watched movies from your watchlist`
    )
  }
}

:host {
  display: block;
}

.container {
  max-width: 800px;
}

// Bulk actions row. Rendered unconditionally so the Clear watched button is
// part of the view even when the watchlist is empty.
.toolbar {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 16px;
}

.clear-watched-btn {
  padding: 6px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background-color: var(--surface);
  color: var(--text-muted);
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s, background-color 0.2s;

  &:hover:not(:disabled) {
    border-color: var(--danger);
    color: var(--danger);
  }

  // Disabled state stays legible: full-contrast text on a muted surface
  &:disabled {
    background-color: var(--surface-muted);
    color: var(--text);
    cursor: not-allowed;
  }
}

.progress {
  height: 6px;
  margin: -8px 0 20px;
  border-radius: 999px;
  background-color: var(--surface-muted);
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  background-color: var(--success);
  transition: width 0.3s ease;
}

.watchlist {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.watchlist-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background-color: var(--surface);
  box-shadow: var(--shadow);
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;

  &:hover {
    border-color: var(--accent);
  }

  &.watched {
    background-color: var(--surface-muted);

    .title-link {
      color: var(--text-muted);
    }
  }
}

.watched-checkbox {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  margin: 0;
  accent-color: var(--success);
  cursor: pointer;
}

.thumb {
  flex-shrink: 0;
  width: 46px;
  height: 69px;
  border-radius: 6px;
  object-fit: cover;
}

.thumb-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--surface-muted);
}

// Text column grows, but the link inside only covers the title text
.item-text {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  min-width: 0;
}

.title-link {
  color: var(--text);
  font-weight: 700;
  text-decoration: none;

  &:hover {
    color: var(--accent);
    text-decoration: underline;
  }
}

.year {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.status-pill {
  flex-shrink: 0;
  padding: 2px 10px;
  border-radius: 999px;
  background-color: var(--surface-muted);
  color: var(--text-muted);
  font-size: 0.8rem;
  font-weight: 600;

  .watched & {
    background-color: var(--surface);
    color: var(--success);
  }

  @media (max-width: 480px) {
    display: none;
  }
}

.remove-btn {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: none;
  border-radius: 50%;
  background: none;
  color: var(--text-muted);
  font-size: 1rem;
  cursor: pointer;

  &:hover {
    background-color: var(--surface-muted);
    color: var(--danger);
  }
}

