    expect(reloaded.items().map((m) => m.id)).toEqual([alien.id]);
    expect(reloaded.watchedCount()).toBe(0);

    store.add(matrix);
    expect(store.items().map((m) => m.id)).toEqual([alien.id, matrix.id]);
  });
